%stage main
%ambiguity-resolution greedy
%const $DEFAULTS $n ↦ {value: $n.span.tokens!'value.join(), image: $n.children!'image.join()}
%rule text $v:w (" " $e:q ≻ " " $e:q)
%conditions $v'value ≠ "unused" ∧ $v'value = $e'value
%rule w ^"a" → {image: value: "no"}
  | ^"a" → {image: value: "yes"}
%rule q ^"a" → {image: value: "yes"}
```

